import { LichTa } from './calendar-engine.js';
import { jdToDate } from './astronomical.js';
import { getKienBranchIndex } from './truc-zodiac.js';

/** Hệ tháng để tra Thần Sát/ngày hoàng đạo; mặc định giữ tháng Kiến theo Tiết Khí. */
export type DayMonthBasis = 'solar-term' | 'lunar';

/** Chi tháng dùng chung cho các API ngày hoàng/hắc đạo, tránh trộn hai hệ quy tắc. */
export function getDayMonthBranchIndex(jd: number, timeZone: number, monthBasis: DayMonthBasis): number {
  if (monthBasis === 'solar-term') return getKienBranchIndex(jd, timeZone);
  if (monthBasis !== 'lunar') {
    throw new RangeError(`Lichta: Month basis must be 'solar-term' or 'lunar', got ${monthBasis}`);
  }
  const [day, month, year] = jdToDate(jd);
  const lunar = LichTa.toLunar(day, month, year, timeZone);
  // Tháng Giêng ứng với Dần (2). Tháng nhuận dùng cùng số tháng âm của tháng thường.
  return (lunar.month + 1) % 12;
}
