import { mod } from '../utils/math.js';
import type { LunarDate } from './types.js';

export interface DayTaboos {
  isTamNuong: boolean;
  isNguyetKy: boolean;
  isDuongCongKyNhat: boolean;
  isSatChuDuong: boolean;
  isSatChuAm: boolean;
  isThoTu: boolean;
  isVangVong: boolean;
  /** Có phạm ít nhất một ngày kỵ hay không */
  hasTaboo: boolean;
  /** Danh sách tên các ngày kỵ phạm phải */
  tabooNames: string[];
}

// ============================================================
// Các ngày kỵ dân gian theo Ngọc Hạp Thông Thư & Lịch Vạn Sự
// ============================================================

/** 6 ngày Tam Nương trong mỗi tháng âm lịch */
const TAM_NUONG_DAYS = new Set([3, 7, 13, 18, 22, 27]);

/** 3 ngày Nguyệt Kỵ trong mỗi tháng âm lịch */
const NGUYET_KY_DAYS = new Set([5, 14, 23]);

/**
 * 13 ngày Dương Công Kỵ Nhật theo tháng âm lịch (tháng 1 -> index 0).
 * Tháng 7 có 2 ngày là ngày 8 và ngày 29.
 */
const DUONG_CONG_KY_DAYS: readonly (readonly number[])[] = [
  [13],       // Tháng 1
  [11],       // Tháng 2
  [9],        // Tháng 3
  [7],        // Tháng 4
  [5],        // Tháng 5
  [3],        // Tháng 6
  [8, 29],    // Tháng 7
  [27],       // Tháng 8
  [25],       // Tháng 9
  [23],       // Tháng 10
  [21],       // Tháng 11
  [19],       // Tháng 12
];

/** Chi Sát Chủ Dương theo tháng 1-12 (Tỵ, Tý, Mùi, Mão, Thân, Tuất, Sửu, Hợi, Ngọ, Dậu, Dần, Thìn) */
const SAT_CHU_DUONG_BRANCHES: readonly number[] = [5, 0, 7, 3, 8, 10, 1, 11, 6, 9, 2, 4];

/** Chi Sát Chủ Âm theo tháng 1-12 (Dần, Tỵ, Thân, Hợi, Mão, Ngọ, Dậu, Tý, Thìn, Mùi, Tuất, Sửu) */
const SAT_CHU_AM_BRANCHES: readonly number[] = [2, 5, 8, 11, 3, 6, 9, 0, 4, 7, 10, 1];

/** Chi Thọ Tử theo tháng 1-12 (Tuất, Thìn, Hợi, Tỵ, Tý, Ngọ, Sửu, Mùi, Dần, Thân, Mão, Dậu) */
const THO_TU_BRANCHES: readonly number[] = [10, 4, 11, 5, 0, 6, 1, 7, 2, 8, 3, 9];

/** Chi Vãng Vong theo tháng 1-12 (Dần, Tỵ, Thân, Hợi, Mão, Ngọ, Dậu, Tý, Thìn, Mùi, Tuất, Sửu) */
const VANG_VONG_BRANCHES: readonly number[] = [2, 5, 8, 11, 3, 6, 9, 0, 4, 7, 10, 1];

/**
 * Kiểm tra ngày âm lịch có phải ngày Tam Nương (mùng 3, 7, 13, 18, 22, 27).
 *
 * @param lunarDay - Ngày âm lịch (1-30)
 */
export function isTamNuong(lunarDay: number): boolean {
  return TAM_NUONG_DAYS.has(lunarDay);
}

/**
 * Kiểm tra ngày âm lịch có phải ngày Nguyệt Kỵ (mùng 5, 14, 23).
 *
 * @param lunarDay - Ngày âm lịch (1-30)
 */
export function isNguyetKy(lunarDay: number): boolean {
  return NGUYET_KY_DAYS.has(lunarDay);
}

/**
 * Kiểm tra ngày có phải là một trong 13 ngày Dương Công Kỵ Nhật trong năm.
 *
 * @param lunarDay - Ngày âm lịch (1-30)
 * @param lunarMonth - Tháng âm lịch (1-12)
 */
export function isDuongCongKyNhat(lunarDay: number, lunarMonth: number): boolean {
  const monthIdx = mod(lunarMonth - 1, 12);
  const targetDays = DUONG_CONG_KY_DAYS[monthIdx];
  return targetDays ? targetDays.includes(lunarDay) : false;
}

/**
 * Kiểm tra ngày có phải ngày Sát Chủ Dương theo tháng và Chi của ngày.
 *
 * @param lunarMonth - Tháng âm lịch (1-12)
 * @param dayBranchIndex - Index Địa Chi của ngày (0-11)
 */
export function isSatChuDuong(lunarMonth: number, dayBranchIndex: number): boolean {
  const monthIdx = mod(lunarMonth - 1, 12);
  return SAT_CHU_DUONG_BRANCHES[monthIdx] === mod(dayBranchIndex, 12);
}

/**
 * Kiểm tra ngày có phải ngày Sát Chủ Âm theo tháng và Chi của ngày.
 *
 * @param lunarMonth - Tháng âm lịch (1-12)
 * @param dayBranchIndex - Index Địa Chi của ngày (0-11)
 */
export function isSatChuAm(lunarMonth: number, dayBranchIndex: number): boolean {
  const monthIdx = mod(lunarMonth - 1, 12);
  return SAT_CHU_AM_BRANCHES[monthIdx] === mod(dayBranchIndex, 12);
}

/**
 * Kiểm tra ngày có phải ngày Thọ Tử theo tháng và Chi của ngày.
 *
 * @param lunarMonth - Tháng âm lịch (1-12)
 * @param dayBranchIndex - Index Địa Chi của ngày (0-11)
 */
export function isThoTu(lunarMonth: number, dayBranchIndex: number): boolean {
  const monthIdx = mod(lunarMonth - 1, 12);
  return THO_TU_BRANCHES[monthIdx] === mod(dayBranchIndex, 12);
}

/**
 * Kiểm tra ngày có phải ngày Vãng Vong theo tháng và Chi của ngày.
 *
 * @param lunarMonth - Tháng âm lịch (1-12)
 * @param dayBranchIndex - Index Địa Chi của ngày (0-11)
 */
export function isVangVong(lunarMonth: number, dayBranchIndex: number): boolean {
  const monthIdx = mod(lunarMonth - 1, 12);
  return VANG_VONG_BRANCHES[monthIdx] === mod(dayBranchIndex, 12);
}

/**
 * Kiểm tra toàn bộ các yếu tố ngày kỵ dân gian của một ngày âm lịch.
 *
 * @param lunar - Đối tượng LunarDate hoặc các thông số ngày, tháng, jd
 */
export function getDayTaboos(lunar: LunarDate): DayTaboos;
export function getDayTaboos(lunarDay: number, lunarMonth: number, jd: number): DayTaboos;
export function getDayTaboos(
  arg1: LunarDate | number,
  arg2?: number,
  arg3?: number
): DayTaboos {
  let day: number;
  let month: number;
  let jd: number;

  if (typeof arg1 === 'object') {
    day = arg1.day;
    month = arg1.month;
    jd = arg1.jd;
  } else {
    day = arg1;
    month = arg2 as number;
    jd = arg3 as number;
  }

  const dayBranchIndex = mod(jd + 1, 12);

  const tamNuong = isTamNuong(day);
  const nguyetKy = isNguyetKy(day);
  const duongCong = isDuongCongKyNhat(day, month);
  const satChuDuong = isSatChuDuong(month, dayBranchIndex);
  const satChuAm = isSatChuAm(month, dayBranchIndex);
  const thoTu = isThoTu(month, dayBranchIndex);
  const vangVong = isVangVong(month, dayBranchIndex);

  const tabooNames: string[] = [];
  if (tamNuong) tabooNames.push('Tam Nương');
  if (nguyetKy) tabooNames.push('Nguyệt Kỵ');
  if (duongCong) tabooNames.push('Dương Công Kỵ Nhật');
  if (satChuDuong) tabooNames.push('Sát Chủ Dương');
  if (satChuAm) tabooNames.push('Sát Chủ Âm');
  if (thoTu) tabooNames.push('Thọ Tử');
  if (vangVong) tabooNames.push('Vãng Vong');

  return {
    isTamNuong: tamNuong,
    isNguyetKy: nguyetKy,
    isDuongCongKyNhat: duongCong,
    isSatChuDuong: satChuDuong,
    isSatChuAm: satChuAm,
    isThoTu: thoTu,
    isVangVong: vangVong,
    hasTaboo: tabooNames.length > 0,
    tabooNames,
  };
}
