/**
 * Ước lượng TT − UT (giây), Espenak/Meeus, NASA 2004.
 * https://eclipse.gsfc.nasa.gov/SEhelp/deltatpoly2004.html
 * Mô hình dự báo này không phải bảng UT1 quan trắc; sai số tăng ở tương lai xa.
 * Các nhánh bên dưới phủ miền lịch 1800–2199 và các sóc/tiết ở năm biên.
 */
export function getDeltaTSeconds(jd: number): number {
  const date = new Date((jd - 2440587.5) * 86400000);
  const year = date.getUTCFullYear() + (date.getUTCMonth() + 0.5) / 12;
  let t: number;
  if (year >= 1700 && year < 1800) {
    t = year - 1700;
    return 8.83 + 0.1603 * t - 0.0059285 * t ** 2 + 0.00013336 * t ** 3 - t ** 4 / 1174000;
  }
  if (year >= 1800 && year < 1860) {
    t = year - 1800;
    return 13.72 - 0.332447 * t + 0.0068612 * t ** 2 + 0.0041116 * t ** 3
      - 0.00037436 * t ** 4 + 0.0000121272 * t ** 5 - 0.0000001699 * t ** 6
      + 0.000000000875 * t ** 7;
  }
  if (year >= 1860 && year < 1900) {
    t = year - 1860;
    return 7.62 + 0.5737 * t - 0.251754 * t ** 2 + 0.01680668 * t ** 3
      - 0.0004473624 * t ** 4 + t ** 5 / 233174;
  }
  if (year >= 1900 && year < 1920) {
    t = year - 1900;
    return -2.79 + 1.494119 * t - 0.0598939 * t ** 2 + 0.0061966 * t ** 3 - 0.000197 * t ** 4;
  }
  if (year >= 1920 && year < 1941) {
    t = year - 1920;
    return 21.20 + 0.84493 * t - 0.076100 * t ** 2 + 0.0020936 * t ** 3;
  }
  if (year >= 1941 && year < 1961) {
    t = year - 1950;
    return 29.07 + 0.407 * t - t ** 2 / 233 + t ** 3 / 2547;
  }
  if (year >= 1961 && year < 1986) {
    t = year - 1975;
    return 45.45 + 1.067 * t - t ** 2 / 260 - t ** 3 / 718;
  }
  if (year >= 1986 && year < 2005) {
    t = year - 2000;
    return 63.86 + 0.3345 * t - 0.060374 * t ** 2 + 0.0017275 * t ** 3
      + 0.000651814 * t ** 4 + 0.00002373599 * t ** 5;
  }
  if (year >= 2005 && year < 2050) {
    t = year - 2000;
    return 62.92 + 0.32217 * t + 0.005589 * t ** 2;
  }
  const longTerm = -20 + 32 * ((year - 1820) / 100) ** 2;
  return year >= 2050 && year < 2150 ? longTerm - 0.5628 * (2150 - year) : longTerm;
}
