import { t, type Locale } from '../constants/i18n.js';
import { mod } from '../utils/math.js';
import { getDayMonthBranchIndex, type DayMonthBasis } from './day-month.js';

export interface ThanSat {
  name: string;
  fullName: string;
  isAuspicious: boolean;
}

// Bảng Khởi Thanh Long tương ứng với 6 nhóm Địa Chi (Tý/Ngọ, Sửu/Mùi, Dần/Thân, Mão/Dậu, Thìn/Tuất, Tỵ/Hợi).
// Giá trị là index Địa Chi bắt đầu đếm Thanh Long.
// 0: Tý/Ngọ -> Thân (8)
// 1: Sửu/Mùi -> Tuất (10)
// 2: Dần/Thân -> Tý (0)
// 3: Mão/Dậu -> Dần (2)
// 4: Thìn/Tuất -> Thìn (4)
// 5: Tỵ/Hợi -> Ngọ (6)
const KHOI_THANH_LONG_TABLE: readonly number[] = [8, 10, 0, 2, 4, 6];

// 6 vị trí của các sao Hoàng Đạo trong danh sách 12 Thần Sát
const AUSPICIOUS_THAN_SAT_INDICES = new Set([0, 1, 4, 5, 7, 10]);

/**
 * Tính thông tin Thần Sát (Hoàng Đạo / Hắc Đạo) cho một Địa Chi đích dựa trên Địa Chi gốc.
 *
 * @param baseBranchIndex - Địa Chi gốc (Giờ: Chi Ngày; Ngày: Chi tháng theo hệ đã chọn)
 * @param targetBranchIndex - Địa Chi đích cần xem Thần Sát
 * @param locale - Ngôn ngữ hiển thị
 * @returns Thông tin Thần Sát (Tên, Tên đầy đủ, Cát/Hung)
 */
function getThanSat(baseBranchIndex: number, targetBranchIndex: number, locale: Locale): ThanSat {
  const groupIndex = mod(baseBranchIndex, 6);
  const khoiThanhLongBranchIndex = KHOI_THANH_LONG_TABLE[groupIndex] as number;
  const thanSatIndex = mod(targetBranchIndex - khoiThanhLongBranchIndex, 12);
  
  const isAuspicious = AUSPICIOUS_THAN_SAT_INDICES.has(thanSatIndex);
  const suffix = isAuspicious ? (locale === 'vi' ? ' Hoàng Đạo' : ' (Auspicious)') : (locale === 'vi' ? ' Hắc Đạo' : ' (Inauspicious)');
  const name = t(locale).thanSat[thanSatIndex] as string;

  return {
    name,
    fullName: name + suffix,
    isAuspicious
  };
}

/**
 * Lấy thông tin Thần Sát (Tên, Hoàng Đạo/Hắc Đạo) của một Giờ cụ thể trong Ngày.
 *
 * @param hour - Giờ (0-23)
 * @param dayJd - Julian Day Number của ngày
 * @param locale - Ngôn ngữ hiển thị (mặc định 'vi')
 */
export function getHourThanSat(hour: number, dayJd: number, locale: Locale = 'vi'): ThanSat {
  const dayBranchIndex = mod(dayJd + 1, 12);
  const hourBranchIndex = mod(Math.floor((hour + 1) / 2), 12);
  return getThanSat(dayBranchIndex, hourBranchIndex, locale);
}

/**
 * Lấy thông tin Thần Sát (Tên, Hoàng Đạo/Hắc Đạo) của một Ngày cụ thể.
 *
 * @param jd - Julian Day Number của ngày
 * @param timeZone - Múi giờ (mặc định 7 cho GMT+7)
 * @param locale - Ngôn ngữ hiển thị (mặc định 'vi')
 * @param monthBasis - 'solar-term': tháng Kiến (mặc định); 'lunar': số tháng âm, tháng nhuận giữ cùng số
 */
export function getDayThanSat(
  jd: number,
  timeZone: number = 7,
  locale: Locale = 'vi',
  monthBasis: DayMonthBasis = 'solar-term'
): ThanSat {
  const monthBranchIndex = getDayMonthBranchIndex(jd, timeZone, monthBasis);
  const dayBranchIndex = mod(jd + 1, 12);
  return getThanSat(monthBranchIndex, dayBranchIndex, locale);
}

// ============================================================
// Nhị Thập Bát Tú (28 Vì Sao)
// ============================================================

/**
 * Lấy index của sao Nhị Thập Bát Tú chiếu trong ngày (0-27).
 * Công thức: mod(Julian Day + 11, 28), với Giác ở index 0.
 * Mốc VNCal 4.5 (Hồ Ngọc Đức): 15/10/2026, JDN 2461329 là sao Giác.
 * Nguồn đối chiếu: duc.cal.gui.MonthModel.getSaoNTBT trong lunar45.jar.
 * Bản lưu: https://honguyenviet.com/amlich/lunar45.jar
 * 
 * @param jd - Julian Day Number của ngày
 */
export function getNhiThapBatTuIndex(jd: number): number {
  return mod(jd + 11, 28);
}

/**
 * Lấy tên của sao Nhị Thập Bát Tú chiếu trong ngày theo locale.
 *
 * @param jd - Julian Day Number của ngày
 * @param locale - Ngôn ngữ hiển thị (mặc định 'vi')
 */
export function getNhiThapBatTu(jd: number, locale: Locale = 'vi'): string {
  const index = getNhiThapBatTuIndex(jd);
  return t(locale).nhiThapBatTu[index] as string;
}
