import { t, type Locale } from '../constants/i18n.js';

export interface DepartureDirections {
  hyThan: string;
  taiThan: string;
}

// Map Thiên Can (0-9) to Hỷ Thần Direction Index (0-7)
// 0: Chính Bắc, 1: Đông Bắc, 2: Chính Đông, 3: Đông Nam, 4: Chính Nam, 5: Tây Nam, 6: Chính Tây, 7: Tây Bắc
const HY_THAN_TABLE: readonly number[] = [1, 7, 5, 4, 3, 1, 7, 5, 4, 3];

// Map Thiên Can (0-9) to Tài Thần Direction Index (0-7)
const TAI_THAN_TABLE: readonly number[] = [3, 3, 2, 2, 0, 4, 5, 5, 7, 0];

/**
 * Lấy hướng Hỷ Thần (Đón niềm vui, may mắn) của một Ngày cụ thể.
 *
 * @param jd - Julian Day Number của ngày
 * @param locale - Ngôn ngữ hiển thị (mặc định 'vi')
 * @returns Hướng Hỷ Thần (vd: 'Đông Bắc')
 */
export function getHyThanDirection(jd: number, locale: Locale = 'vi'): string {
  const canIndex = (jd + 9) % 10; // Tính Thiên Can của ngày
  const directionIndex = HY_THAN_TABLE[canIndex] as number;
  return t(locale).directions[directionIndex] as string;
}

/**
 * Lấy hướng Tài Thần (Đón tài lộc, tiền bạc) của một Ngày cụ thể.
 *
 * @param jd - Julian Day Number của ngày
 * @param locale - Ngôn ngữ hiển thị (mặc định 'vi')
 * @returns Hướng Tài Thần (vd: 'Đông Nam')
 */
export function getTaiThanDirection(jd: number, locale: Locale = 'vi'): string {
  const canIndex = (jd + 9) % 10; // Tính Thiên Can của ngày
  const directionIndex = TAI_THAN_TABLE[canIndex] as number;
  return t(locale).directions[directionIndex] as string;
}

/**
 * Lấy thông tin Hướng Xuất Hành (Hỷ Thần, Tài Thần) của một Ngày cụ thể.
 *
 * @param jd - Julian Day Number của ngày
 * @param locale - Ngôn ngữ hiển thị (mặc định 'vi')
 * @returns Đối tượng chứa hướng Hỷ Thần và Tài Thần
 */
export function getDepartureDirections(jd: number, locale: Locale = 'vi'): DepartureDirections {
  return {
    hyThan: getHyThanDirection(jd, locale),
    taiThan: getTaiThanDirection(jd, locale)
  };
}
