import { t, type Locale } from '../constants/i18n.js';
import { mod } from '../utils/math.js';

export interface LyThuanPhongHour {
  /** Index cung Lý Thuần Phong (0: Đại An, 1: Lưu Niên, 2: Tốc Hỷ, 3: Xích Khẩu, 4: Tiểu Cát, 5: Không Vong) */
  index: number;
  /** Tên cung theo locale (ví dụ: 'Đại An') */
  name: string;
  /** Tính chất cát hung: true nếu là giờ tốt (Đại An, Tốc Hỷ, Tiểu Cát), false nếu là giờ xấu (Lưu Niên, Xích Khẩu, Không Vong) */
  isAuspicious: boolean;
  /** Index Địa Chi của giờ (0-11: Tý → Hợi) */
  branchIndex: number;
  /** Tên Địa Chi của giờ theo locale (ví dụ: 'Tý') */
  branchName: string;
}

// 0: Đại An (Tốt), 1: Lưu Niên (Xấu/Chậm), 2: Tốc Hỷ (Tốt), 3: Xích Khẩu (Xấu), 4: Tiểu Cát (Tốt), 5: Không Vong (Xấu)
const AUSPICIOUS_INDICES = new Set([0, 2, 4]);

/**
 * Tính index cung giờ xuất hành Lý Thuần Phong (Lục Nhâm: 0-5).
 *
 * Quy tắc tính:
 *   - Tháng Giêng khởi từ Đại An (0), cứ mỗi tháng tiến 1 cung theo chiều thuận: monthStart = (tháng - 1) % 6.
 *   - Ngày mùng 1 khởi từ cung của tháng, mỗi ngày tiến 1 cung theo chiều thuận: dayStart = (monthStart + ngày - 1) % 6.
 *   - Giờ Tý khởi từ cung của ngày, mỗi canh giờ tiến 1 cung theo chiều thuận: hourIndex = (dayStart + hourBranchIndex) % 6.
 *
 * @param lunarDay - Ngày âm lịch (1-30)
 * @param lunarMonth - Tháng âm lịch (1-12)
 * @param hourBranchIndex - Index Địa Chi của giờ (0-11, 0: Tý, 1: Sửu, ..., 11: Hợi)
 * @returns Index cung Lý Thuần Phong (0-5)
 */
export function getLyThuanPhongIndex(
  lunarDay: number,
  lunarMonth: number,
  hourBranchIndex: number
): number {
  const monthStart = mod(lunarMonth - 1, 6);
  const dayStart = mod(monthStart + lunarDay - 1, 6);
  return mod(dayStart + hourBranchIndex, 6);
}

/**
 * Lấy thông tin giờ xuất hành Lý Thuần Phong tại một giờ cụ thể trong ngày âm lịch.
 *
 * @param lunarDay - Ngày âm lịch (1-30)
 * @param lunarMonth - Tháng âm lịch (1-12)
 * @param hour - Giờ trong ngày (0-23)
 * @param locale - Ngôn ngữ hiển thị (mặc định 'vi')
 */
export function getLyThuanPhongHour(
  lunarDay: number,
  lunarMonth: number,
  hour: number,
  locale: Locale = 'vi'
): LyThuanPhongHour {
  // Tính Địa Chi của giờ: 23h-01h = Tý (0), 01h-03h = Sửu (1), v.v.
  const branchIndex = mod(Math.floor((hour + 1) / 2), 12);
  const index = getLyThuanPhongIndex(lunarDay, lunarMonth, branchIndex);
  const { lyThuanPhong, earthlyBranches } = t(locale);

  return {
    index,
    name: lyThuanPhong[index] as string,
    isAuspicious: AUSPICIOUS_INDICES.has(index),
    branchIndex,
    branchName: earthlyBranches[branchIndex] as string,
  };
}

/**
 * Lấy danh sách thông tin xuất hành Lý Thuần Phong cho toàn bộ 12 canh giờ trong ngày âm lịch.
 *
 * @param lunarDay - Ngày âm lịch (1-30)
 * @param lunarMonth - Tháng âm lịch (1-12)
 * @param locale - Ngôn ngữ hiển thị (mặc định 'vi')
 */
export function getAllLyThuanPhongHoursOfDay(
  lunarDay: number,
  lunarMonth: number,
  locale: Locale = 'vi'
): LyThuanPhongHour[] {
  const result: LyThuanPhongHour[] = [];
  const { lyThuanPhong, earthlyBranches } = t(locale);
  const monthStart = mod(lunarMonth - 1, 6);
  const dayStart = mod(monthStart + lunarDay - 1, 6);

  for (let branchIndex = 0; branchIndex < 12; branchIndex++) {
    const index = mod(dayStart + branchIndex, 6);
    result.push({
      index,
      name: lyThuanPhong[index] as string,
      isAuspicious: AUSPICIOUS_INDICES.has(index),
      branchIndex,
      branchName: earthlyBranches[branchIndex] as string,
    });
  }

  return result;
}
