import type { LunarDate, SolarDate } from './types.js';
import { HEAVENLY_STEMS } from '../constants/heavenly-stems.js';
import { EARTHLY_BRANCHES } from '../constants/earthly-branches.js';
import { jdFromDate, jdToDate, getNewMoonDay, getSunLongitude } from './astronomical.js';

/**
 * `LichTa.toLunar`/`toSolar` — chuyển đổi Dương lịch ↔ Âm lịch Việt Nam.
 * Xây dựng trên các hàm thiên văn thuần túy ở `astronomical.ts` (Điểm Sóc, Tiết Khí)
 * để xác định ranh giới tháng âm lịch, bao gồm tháng nhuận.
 */

function INT(d: number): number {
  return Math.floor(d);
}

function validateInteger(value: number, min: number, max: number, name: string): void {
  if (!Number.isInteger(value) || value < min || value > max) {
    throw new RangeError(`Lichta: ${name} must be an integer between ${min} and ${max}, got ${value}`);
  }
}

function validateTimeZone(timeZone: number): void {
  if (!Number.isFinite(timeZone) || timeZone < -12 || timeZone > 14) {
    throw new RangeError(`Lichta: Time zone must be between -12 and 14, got ${timeZone}`);
  }
}

// ============================================================
// Tháng 11 âm lịch & Tháng nhuận
// ============================================================

/**
 * Tìm JDN của mùng 1 tháng 11 âm lịch (tháng chứa Đông Chí).
 */
function getLunarMonth11(yy: number, timeZone: number): number {
  const off = jdFromDate(31, 12, yy) - 2415021.076998695;
  const k = INT(off / 29.530588853);
  let nm = getNewMoonDay(k, timeZone);
  const sunLong = getSunLongitude(nm, timeZone);
  if (sunLong >= 9) {
    nm = getNewMoonDay(k - 1, timeZone);
  }
  return nm;
}

/**
 * Tìm offset tháng nhuận (tháng đầu tiên không chứa Trung khí
 * giữa 2 tháng 11 âm lịch liên tiếp).
 */
function getLeapMonthOffset(a11: number, timeZone: number): number {
  const k = INT((a11 - 2415021.076998695) / 29.530588853 + 0.5);
  let last: number;
  let i = 1;
  let arc = getSunLongitude(getNewMoonDay(k + i, timeZone), timeZone);
  last = arc;
  while (i < 14) {
    i++;
    arc = getSunLongitude(getNewMoonDay(k + i, timeZone), timeZone);
    if (arc !== last) {
      last = arc;
    } else {
      // 2 tháng liên tiếp cùng Trung khí → tháng trước đó là tháng nhuận
      break;
    }
  }
  return i - 1;
}

/** Đổi offset sóc trong chu kỳ tháng 11 thành số tháng 1–12, kể cả tháng 12 nhuận. */
function getLeapMonthNumber(offset: number): number {
  return (offset + 9) % 12 + 1;
}

/**
 * Ranh giới tháng âm đã xác thực, dùng chung cho đổi lịch và tính độ dài tháng.
 * Tháng 11/12 và tháng 1–10 thuộc hai chu kỳ Đông Chí khác nhau của cùng năm âm.
 */
function getLunarMonthBounds(
  lunarMonth: number,
  lunarYear: number,
  isLeap: boolean,
  timeZone: number
): [number, number] {
  validateInteger(lunarYear, 1800, 2199, 'Year');
  validateInteger(lunarMonth, 1, 12, 'Month');
  validateTimeZone(timeZone);
  if (typeof isLeap !== 'boolean') {
    throw new RangeError('Lichta: isLeap must be a boolean');
  }

  const cycleYear = lunarMonth < 11 ? lunarYear - 1 : lunarYear;
  const a11 = getLunarMonth11(cycleYear, timeZone);
  const b11 = getLunarMonth11(cycleYear + 1, timeZone);
  const k = INT(0.5 + (a11 - 2415021.076998695) / 29.530588853);
  let off = (lunarMonth + 1) % 12;

  if (b11 - a11 > 365) {
    const leapOff = getLeapMonthOffset(a11, timeZone);
    const leapMonth = getLeapMonthNumber(leapOff);
    if (isLeap && lunarMonth !== leapMonth) {
      throw new RangeError(`Lichta: Month ${lunarMonth} is not a leap month in lunar year ${lunarYear}`);
    }
    if (isLeap || off >= leapOff) off += 1;
  } else if (isLeap) {
    throw new RangeError(`Lichta: Month ${lunarMonth} is not a leap month in lunar year ${lunarYear}`);
  }

  return [getNewMoonDay(k + off, timeZone), getNewMoonDay(k + off + 1, timeZone)];
}

// ============================================================
// Can Chi helpers
// ============================================================

function getYearCanChi(lunarYear: number): string {
  const stemIndex = (lunarYear + 6) % 10;
  const branchIndex = (lunarYear + 8) % 12;
  return `${HEAVENLY_STEMS[stemIndex]} ${EARTHLY_BRANCHES[branchIndex]}`;
}

function getMonthCanChiInternal(lunarMonth: number, lunarYear: number): string {
  const yearStemIndex = (lunarYear + 6) % 10;
  const monthStemOffset = (yearStemIndex % 5) * 2 + 2;
  const monthStemIndex = (monthStemOffset + lunarMonth - 1) % 10;
  const monthBranchIndex = (lunarMonth + 1) % 12;
  return `${HEAVENLY_STEMS[monthStemIndex]} ${EARTHLY_BRANCHES[monthBranchIndex]}`;
}

function getDayCanChiInternal(jd: number): string {
  const stemIndex = (jd + 9) % 10;
  const branchIndex = (jd + 1) % 12;
  return `${HEAVENLY_STEMS[stemIndex]} ${EARTHLY_BRANCHES[branchIndex]}`;
}

// ============================================================
// LichTa — Public API
// ============================================================

export class LichTa {
  /**
   * Chuyển đổi ngày Dương lịch sang Âm lịch.
   *
   * Sử dụng thuật toán Hồ Ngọc Đức để tìm Điểm Sóc và Tiết Khí,
   * từ đó xác định ngày, tháng, năm âm lịch tương ứng.
   *
   * @param day - Ngày dương lịch (1-31)
   * @param month - Tháng dương lịch (1-12)
   * @param year - Năm dương lịch (1800-2199)
   * @param timeZone - Múi giờ (mặc định: 7 cho GMT+7 Việt Nam)
   * @returns Đối tượng LunarDate chứa thông tin ngày âm lịch
   * @throws {RangeError} Khi input ngoài phạm vi hợp lệ
   *
   * @example
   * ```typescript
   * const lunar = LichTa.toLunar(10, 2, 2024);
   * // → { day: 1, month: 1, year: 2024, isLeap: false, yearCanChi: 'Giáp Thìn' }
   * ```
   */
  static toLunar(day: number, month: number, year: number, timeZone: number = 7): LunarDate {
    validateInteger(year, 1800, 2199, 'Year');
    validateInteger(month, 1, 12, 'Month');
    const daysInMonth = new Date(Date.UTC(year, month, 0)).getUTCDate();
    validateInteger(day, 1, daysInMonth, 'Day');
    validateTimeZone(timeZone);

    const dayNumber = jdFromDate(day, month, year);
    let k = INT((dayNumber - 2415021.076998695) / 29.530588853);

    // k chỉ là ước lượng sóc trung bình. Tìm đúng hai sóc bao quanh ngày cần đổi,
    // thay vì giả định lùi một lần luôn đủ (có thể sinh ngày âm bằng 0).
    let monthStart = getNewMoonDay(k, timeZone);
    while (monthStart > dayNumber) {
      monthStart = getNewMoonDay(--k, timeZone);
    }
    let nextMonthStart = getNewMoonDay(k + 1, timeZone);
    while (nextMonthStart <= dayNumber) {
      monthStart = nextMonthStart;
      nextMonthStart = getNewMoonDay(++k + 1, timeZone);
    }

    let a11 = getLunarMonth11(year, timeZone);
    let b11 = a11;
    let lunarYear: number;
    if (a11 >= monthStart) {
      lunarYear = year;
      a11 = getLunarMonth11(year - 1, timeZone);
    } else {
      lunarYear = year + 1;
      b11 = getLunarMonth11(year + 1, timeZone);
    }

    const lunarDay = dayNumber - monthStart + 1;
    const diff = INT((monthStart - a11) / 29);

    // Kiểm tra tháng nhuận: một năm âm lịch nhuận có 13 tháng (~384 ngày)
    // thay vì 12 tháng (~354 ngày) giữa 2 mốc tháng 11.
    let lunarLeap = false;
    let lunarMonth = diff + 11;
    if (b11 - a11 > 365) {
      const leapMonthDiff = getLeapMonthOffset(a11, timeZone);
      if (diff >= leapMonthDiff) {
        lunarMonth = diff + 10;
        if (diff === leapMonthDiff) {
          lunarLeap = true;
        }
      }
    }
    if (lunarMonth > 12) {
      lunarMonth -= 12;
    }
    if (lunarMonth >= 11 && diff < 4) {
      lunarYear -= 1;
    }

    const yearCanChi = getYearCanChi(lunarYear);
    const monthCanChi = getMonthCanChiInternal(lunarMonth, lunarYear);
    const dayCanChi = getDayCanChiInternal(dayNumber);

    return {
      day: lunarDay,
      month: lunarMonth,
      year: lunarYear,
      isLeap: lunarLeap,
      jd: dayNumber,
      dayCanChi,
      monthCanChi,
      yearCanChi,
    };
  }

  /**
   * Chuyển đổi ngày Âm lịch sang Dương lịch.
   *
   * @param lunarDay - Ngày âm lịch
   * @param lunarMonth - Tháng âm lịch
   * @param lunarYear - Năm âm lịch
   * @param isLeap - Có phải tháng nhuận không
   * @param timeZone - Múi giờ (mặc định: 7 cho GMT+7 Việt Nam)
   * @returns Đối tượng SolarDate
   * @throws {RangeError} Khi ngày, tháng, năm, tháng nhuận hoặc múi giờ không hợp lệ
   *
   * @example
   * ```typescript
   * const solar = LichTa.toSolar(1, 1, 2024, false);
   * // → { day: 10, month: 2, year: 2024 }
   * ```
   */
  static toSolar(
    lunarDay: number,
    lunarMonth: number,
    lunarYear: number,
    isLeap: boolean = false,
    timeZone: number = 7
  ): SolarDate {
    const [nm, nextMonthStart] = getLunarMonthBounds(lunarMonth, lunarYear, isLeap, timeZone);
    validateInteger(lunarDay, 1, nextMonthStart - nm, 'Lunar day');
    const jd = nm + lunarDay - 1;
    const [day, month, year] = jdToDate(jd);

    return { day, month, year };
  }

  /**
   * Chuyển đổi đối tượng Date của JavaScript sang Âm lịch.
   *
   * @param date - Đối tượng Date của JS
   * @param timeZone - Múi giờ (mặc định: 7 cho GMT+7 Việt Nam)
   */
  static fromDate(date: Date, timeZone: number = 7): LunarDate {
    return LichTa.toLunar(date.getDate(), date.getMonth() + 1, date.getFullYear(), timeZone);
  }

  /**
   * Lấy ngày Âm lịch của ngày hôm nay theo thời gian hệ thống.
   *
   * @param timeZone - Múi giờ (mặc định: 7 cho GMT+7 Việt Nam)
   */
  static today(timeZone: number = 7): LunarDate {
    return LichTa.fromDate(new Date(), timeZone);
  }

  /**
   * Lấy tháng nhuận của một năm âm lịch.
   *
   * @param lunarYear - Năm âm lịch (1800-2199)
   * @param timeZone - Múi giờ (mặc định: 7 cho GMT+7 Việt Nam)
   * @returns Số tháng nhuận (1-12) hoặc 0 nếu năm đó không nhuận.
   */
  static getLeapMonth(lunarYear: number, timeZone: number = 7): number {
    validateInteger(lunarYear, 1800, 2199, 'Year');
    validateTimeZone(timeZone);
    const a11 = getLunarMonth11(lunarYear - 1, timeZone);
    const b11 = getLunarMonth11(lunarYear, timeZone);
    if (b11 - a11 > 365) {
      const leapMonth = getLeapMonthNumber(getLeapMonthOffset(a11, timeZone));
      // Tháng 11/12 nhuận của chu kỳ này thuộc năm âm trước.
      if (leapMonth < 11) return leapMonth;
    }
    const c11 = getLunarMonth11(lunarYear + 1, timeZone);
    if (c11 - b11 > 365) {
      const leapMonth = getLeapMonthNumber(getLeapMonthOffset(b11, timeZone));
      // Nhuận cuối năm nằm sau tháng 11 của chính năm đang hỏi.
      if (leapMonth >= 11) return leapMonth;
    }
    return 0;
  }

  /**
   * Tính số ngày trong một tháng âm lịch (29 ngày = tháng thiếu, 30 ngày = tháng đủ).
   *
   * @param lunarMonth - Tháng âm lịch (1-12)
   * @param lunarYear - Năm âm lịch (1800-2199)
   * @param isLeap - Có phải tháng nhuận không (mặc định: false)
   * @param timeZone - Múi giờ (mặc định: 7)
   * @returns 29 hoặc 30
   * @throws {RangeError} Khi năm/tháng/múi giờ không hợp lệ hoặc tháng nhuận không tồn tại
   */
  static getDaysInLunarMonth(
    lunarMonth: number,
    lunarYear: number,
    isLeap: boolean = false,
    timeZone: number = 7
  ): number {
    const [nmCurrent, nmNext] = getLunarMonthBounds(lunarMonth, lunarYear, isLeap, timeZone);
    return nmNext - nmCurrent;
  }
}
