import { EARTH_LONGITUDE_TERMS, EARTH_RADIUS_TERMS } from '../constants/earth-orbit.js';
import { mod } from '../utils/math.js';
import { getDeltaTSeconds } from './time-scale.js';

const DEG = Math.PI / 180;
const longitudeCache = new Map<number, number>();
type OrbitSeries = readonly (readonly (readonly [number, number, number])[])[];

function evaluateSeries(series: OrbitSeries, t: number): number {
  let result = 0;
  for (let power = series.length - 1; power >= 0; power--) {
    let sum = 0;
    for (const [amplitude, phase, frequency] of series[power]) {
      sum += amplitude * Math.cos(phase + frequency * t);
    }
    result = result * t + sum;
  }
  return result;
}

/**
 * Kinh độ Mặt Trời biểu kiến tại Julian Date UT (độ, 0–360).
 * Quỹ đạo Trái Đất VSOP87D, đổi sang hệ FK5 và cộng chương động/quang sai.
 * Thời gian tính quỹ đạo là TT; đầu vào UT được đổi theo Delta T của NASA.
 * Đối chứng ngày giao tiết: https://eco.mtk.nao.ac.jp/koyomi/yoko/index.html
 */
export function getApparentSunLongitude(jd: number): number {
  const cached = longitudeCache.get(jd);
  if (cached !== undefined) return cached;

  const jde = jd + getDeltaTSeconds(jd) / 86400;
  const t = (jde - 2451545) / 365250;
  const centuries = t * 10;
  const longitude = evaluateSeries(EARTH_LONGITUDE_TERMS, t) / DEG + 180;
  const radius = evaluateSeries(EARTH_RADIUS_TERMS, t);
  const omega = (125.04452 - 1934.136261 * centuries + 0.0020708 * centuries ** 2
    + centuries ** 3 / 450000) * DEG;
  const sunMean = (280.4665 + 36000.7698 * centuries) * DEG;
  const moonMean = (218.3165 + 481267.8813 * centuries) * DEG;
  // Bốn số hạng chương động chính, Meeus chương 22 (đơn vị giây cung).
  const nutation = -17.20 * Math.sin(omega) - 1.32 * Math.sin(2 * sunMean)
    - 0.23 * Math.sin(2 * moonMean) + 0.21 * Math.sin(2 * omega);
  const apparent = mod(longitude + (nutation - 20.4898 / radius - 0.09033) / 3600, 360);

  // Dùng lại các ngày sóc khi tìm Trung khí, giới hạn bộ nhớ khi duyệt nhiều năm.
  if (longitudeCache.size >= 1024) longitudeCache.clear();
  longitudeCache.set(jd, apparent);
  return apparent;
}
