import { LichTa } from './calendar-engine.js';
import { jdToDate } from './astronomical.js';
import type { LunarDate } from './types.js';

/**
 * Cộng hoặc trừ số ngày vào một ngày âm lịch.
 * Tự động xử lý chính xác tháng thiếu (29 ngày), tháng đủ (30 ngày), tháng nhuận và đổi năm.
 *
 * @param lunar - Ngày âm lịch ban đầu
 * @param days - Số ngày cần cộng (dương) hoặc trừ (âm)
 * @param timeZone - Múi giờ (mặc định: 7)
 * @returns Đối tượng LunarDate mới sau khi cộng/trừ ngày
 *
 * @example
 * ```typescript
 * const tet = LichTa.toLunar(10, 2, 2024); // Mùng 1 Tết Giáp Thìn
 * const mung2 = addDays(tet, 1);           // Mùng 2 Tết
 * const tatNien = addDays(tet, -1);        // Ngày 30 (hoặc 29) tháng Chạp năm trước
 * ```
 */
export function addDays(lunar: LunarDate, days: number, timeZone: number = 7): LunarDate {
  if (days === 0) return lunar;
  const newJd = lunar.jd + days;
  const [day, month, year] = jdToDate(newJd);
  return LichTa.toLunar(day, month, year, timeZone);
}

/**
 * Tính khoảng cách số ngày giữa hai ngày âm lịch (lunarA - lunarB).
 *
 * @param lunarA - Ngày âm lịch thứ nhất
 * @param lunarB - Ngày âm lịch thứ hai
 * @returns Số ngày chênh lệch (dương nếu A sau B, âm nếu A trước B, 0 nếu cùng ngày)
 */
export function diffDays(lunarA: LunarDate, lunarB: LunarDate): number {
  return lunarA.jd - lunarB.jd;
}

/**
 * Kiểm tra hai ngày âm lịch có phải là cùng một ngày hay không.
 *
 * @param lunarA - Ngày âm lịch thứ nhất
 * @param lunarB - Ngày âm lịch thứ hai
 */
export function isSameDay(lunarA: LunarDate, lunarB: LunarDate): boolean {
  return lunarA.jd === lunarB.jd;
}

/**
 * Kiểm tra ngày âm lịch A có diễn ra trước ngày âm lịch B hay không.
 *
 * @param lunarA - Ngày âm lịch thứ nhất
 * @param lunarB - Ngày âm lịch thứ hai
 */
export function isBefore(lunarA: LunarDate, lunarB: LunarDate): boolean {
  return lunarA.jd < lunarB.jd;
}

/**
 * Kiểm tra ngày âm lịch A có diễn ra sau ngày âm lịch B hay không.
 *
 * @param lunarA - Ngày âm lịch thứ nhất
 * @param lunarB - Ngày âm lịch thứ hai
 */
export function isAfter(lunarA: LunarDate, lunarB: LunarDate): boolean {
  return lunarA.jd > lunarB.jd;
}
