import { getDeltaTSeconds } from './time-scale.js';

const DEG = Math.PI / 180;
const newMoonCache = new Map<number, number>();

/**
 * Sóc theo Meeus, Astronomical Algorithms (1998), chương 49.
 * k = 0 là sóc 06/01/2000; trả Julian Date theo UT, trước khi quy về ngày địa phương.
 * Gồm 25 hiệu chỉnh pha và 14 hiệu chỉnh hành tinh; TT → UT theo mô hình NASA.
 * Đối chứng: https://eclipse.gsfc.nasa.gov/phase/phasecat.html
 */
export function getNewMoonTime(k: number): number {
  const cached = newMoonCache.get(k);
  if (cached !== undefined) return cached;

  const T = k / 1236.85;
  const T2 = T * T;
  const T3 = T2 * T;
  const T4 = T3 * T;
  const sin = (angle: number) => Math.sin(angle * DEG);
  const E = 1 - 0.002516 * T - 0.0000074 * T2;
  const M = 2.5534 + 29.10535670 * k - 0.0000014 * T2 - 0.00000011 * T3;
  const moonAnomaly = 201.5643 + 385.81693528 * k + 0.0107582 * T2
    + 0.00001238 * T3 - 0.000000058 * T4;
  const F = 160.7108 + 390.67050284 * k - 0.0016118 * T2 - 0.00000227 * T3 + 0.000000011 * T4;
  const omega = 124.7746 - 1.56375588 * k + 0.0020672 * T2 + 0.00000215 * T3;

  let jde = 2451550.09765 + 29.530588853 * k + 0.0001337 * T2
    - 0.000000150 * T3 + 0.00000000073 * T4;
  const corrections = [
    [-0.40720, moonAnomaly], [0.17241 * E, M], [0.01608, 2 * moonAnomaly],
    [0.01039, 2 * F], [0.00739 * E, moonAnomaly - M], [-0.00514 * E, moonAnomaly + M],
    [0.00208 * E * E, 2 * M], [-0.00111, moonAnomaly - 2 * F],
    [-0.00057, moonAnomaly + 2 * F], [0.00056 * E, 2 * moonAnomaly + M],
    [-0.00042, 3 * moonAnomaly], [0.00042 * E, M + 2 * F], [0.00038 * E, M - 2 * F],
    [-0.00024 * E, 2 * moonAnomaly - M], [-0.00017, omega], [-0.00007, moonAnomaly + 2 * M],
    [0.00004, 2 * moonAnomaly - 2 * F], [0.00004, 3 * M],
    [0.00003, moonAnomaly + M - 2 * F], [0.00003, 2 * moonAnomaly + 2 * F],
    [-0.00003, moonAnomaly + M + 2 * F], [0.00003, moonAnomaly - M + 2 * F],
    [-0.00002, moonAnomaly - M - 2 * F], [-0.00002, 3 * moonAnomaly + M],
    [0.00002, 4 * moonAnomaly],
    [0.000325, 299.77 + 0.107408 * k - 0.009173 * T2],
    [0.000165, 251.88 + 0.016321 * k], [0.000164, 251.83 + 26.651886 * k],
    [0.000126, 349.42 + 36.412478 * k], [0.000110, 84.66 + 18.206239 * k],
    [0.000062, 141.74 + 53.303771 * k], [0.000060, 207.14 + 2.453732 * k],
    [0.000056, 154.84 + 7.306860 * k], [0.000047, 34.52 + 27.261239 * k],
    [0.000042, 207.19 + 0.121824 * k], [0.000040, 291.34 + 1.844379 * k],
    [0.000037, 161.72 + 24.198154 * k], [0.000035, 239.56 + 25.513099 * k],
    [0.000023, 331.55 + 3.592518 * k],
  ];
  for (const [amplitude, angle] of corrections) jde += amplitude * sin(angle);
  const jd = jde - getDeltaTSeconds(jde) / 86400;

  // Cache có giới hạn; thời điểm sóc độc lập múi giờ và được dùng lại khi đổi lịch.
  if (newMoonCache.size >= 512) newMoonCache.clear();
  newMoonCache.set(k, jd);
  return jd;
}
