import { LichTa } from '../core/calendar-engine.js';
import type { LunarDate } from '../core/types.js';
import { t, type Locale } from '../constants/i18n.js';

/**
 * Phân tích cú pháp chuỗi ngày âm lịch theo mẫu định dạng (pattern).
 *
 * **Các token hỗ trợ trong pattern:**
 * | Token | Mô tả | Ví dụ |
 * |---|---|---|
 * | `yyyy` | Năm 4 chữ số | 2024 |
 * | `yy` | Năm 2 chữ số (>= 70 tính là 19xx, < 70 tính là 20xx) | 24 |
 * | `MM` | Tháng 2 chữ số (01-12) | 01, 08 |
 * | `M` | Tháng 1-2 chữ số (1-12) | 1, 8 |
 * | `dd` | Ngày 2 chữ số (01-30) | 01, 15 |
 * | `d` | Ngày 1-2 chữ số (1-30) | 1, 15 |
 * | `L` | Nhãn tháng nhuận ("Nhuận" cho vi, "Leap" cho en, v.v.) | Nhuận |
 *
 * @param dateStr - Chuỗi ngày âm lịch cần phân tích
 * @param pattern - Chuỗi pattern định dạng (ví dụ: 'dd/MM/yyyy', 'd/M/yyyy L')
 * @param locale - Ngôn ngữ cho token L (mặc định: 'vi')
 * @returns Đối tượng LunarDate hoàn chỉnh
 * @throws {Error} Nếu chuỗi không khớp với pattern hoặc ngày âm lịch không hợp lệ
 *
 * @example
 * ```typescript
 * const lunar = parseLunarDate('15/08/2024', 'dd/MM/yyyy');
 * // → { day: 15, month: 8, year: 2024, isLeap: false, ... }
 *
 * const leapLunar = parseLunarDate('15/02/2023 Nhuận', 'dd/MM/yyyy L');
 * // → { day: 15, month: 2, year: 2023, isLeap: true, ... }
 * ```
 */
export function parseLunarDate(
  dateStr: string,
  pattern: string,
  locale: Locale = 'vi'
): LunarDate {
  const tokenRegexMap: { [key: string]: { regex: string; key: string } } = {
    yyyy: { regex: '(\\d{4})', key: 'year' },
    yy: { regex: '(\\d{2})', key: 'shortYear' },
    MM: { regex: '(\\d{2})', key: 'month' },
    M: { regex: '(\\d{1,2})', key: 'month' },
    dd: { regex: '(\\d{2})', key: 'day' },
    d: { regex: '(\\d{1,2})', key: 'day' },
    L: { regex: '(.*?)', key: 'leap' },
  };

  // Sắp xếp các token theo độ dài giảm dần để ưu tiên match token dài trước (yyyy trước yy, dd trước d...)
  const tokens = ['yyyy', 'yy', 'MM', 'dd', 'd', 'M', 'L'];
  const tokenKeys: string[] = [];

  // Tạo biểu thức chính quy từ pattern
  let regexStr = '^';
  let i = 0;
  while (i < pattern.length) {
    let matchedToken: string | null = null;
    for (const t of tokens) {
      if (pattern.startsWith(t, i)) {
        matchedToken = t;
        break;
      }
    }

    if (matchedToken) {
      const config = tokenRegexMap[matchedToken];
      regexStr += config.regex;
      tokenKeys.push(config.key);
      i += matchedToken.length;
    } else {
      // Escape các ký tự đặc biệt của regex
      const char = pattern[i];
      regexStr += /[\\^$*+?.()|[\]{}]/.test(char) ? `\\${char}` : char;
      i++;
    }
  }
  regexStr += '$';

  const match = new RegExp(regexStr).exec(dateStr.trim());
  if (!match) {
    throw new Error(
      `Lichta: Date string "${dateStr}" does not match pattern "${pattern}"`
    );
  }

  const values: { [key: string]: string } = {};
  for (let k = 0; k < tokenKeys.length; k++) {
    values[tokenKeys[k]] = match[k + 1];
  }

  // Trích xuất ngày, tháng, năm
  let year: number;
  if (values.year) {
    year = parseInt(values.year, 10);
  } else if (values.shortYear) {
    const sy = parseInt(values.shortYear, 10);
    year = sy >= 70 ? 1900 + sy : 2000 + sy;
  } else {
    throw new Error(`Lichta: Pattern "${pattern}" must include year (yyyy or yy)`);
  }

  if (!values.month) {
    throw new Error(`Lichta: Pattern "${pattern}" must include month (MM or M)`);
  }
  const month = parseInt(values.month, 10);

  if (!values.day) {
    throw new Error(`Lichta: Pattern "${pattern}" must include day (dd or d)`);
  }
  const day = parseInt(values.day, 10);

  // Xác định isLeap
  let isLeap = false;
  if (values.leap) {
    const leapStr = values.leap.trim().toLowerCase();
    const expectedLeap = t(locale).leapLabel.toLowerCase();
    if (leapStr.includes(expectedLeap) || leapStr.includes('nhuận') || leapStr.includes('leap')) {
      isLeap = true;
    }
  }

  // Chuyển sang Dương lịch qua LichTa.toSolar để thẩm định tính hợp lệ
  const solar = LichTa.toSolar(day, month, year, isLeap);

  // Chuyển lại thành LunarDate hoàn chỉnh với đầy đủ Can Chi, JDN
  return LichTa.toLunar(solar.day, solar.month, solar.year);
}
